package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class PymolPotentialCliTest {
    @TempDir Path root;
    static Map<String,String> model(){String[] fields={"charge-model","explicit supplied-PQR model","length-units","angstrom","value-units","kt-per-e","temperature","298.15","surface-radii","source-pqr","surface-solvent","excluded","probe-radius","1.4","sample-location","surface","surface-quality","1","ramp-range","-5,0,5","low-color","1,0,0","middle-color","1,1,1","high-color","0,0,1","background","1,1,1","width","1200","height","1000","buffer","6"};var result=new LinkedHashMap<String,String>();for(int i=0;i<fields.length;i+=2)result.put(fields[i],fields[i+1]);return result;}
    private record Run(int code,String out,String err) { }
    private static Run run(String... args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int code=PymolPotentialCli.run(args,new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8));return new Run(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    private static Run run(Map<String,String> options){var args=new ArrayList<String>();options.forEach((k,v)->{args.add("--"+k);args.add(v);});return run(args.toArray(String[]::new));}
    private Map<String,String> options(String name)throws Exception {var f=PymolPotentialAuditTest.fixture(root.resolve("input-"+name));var values=model();values.put("input",f.directory().resolve("source.pqr").toString());values.put("grid",f.directory().resolve("potential.dx").toString());values.put("home",root.resolve("absent-home").toString());values.put("out",root.resolve(name).toString());return values;}
    private static void status(Map<String,String> options,String expected)throws Exception {Path out=Path.of(options.get("out"));assertTrue(Files.readString(out.resolve("analysis-status.json")).contains(expected));assertTrue(Files.readString(out.resolve("WARNINGS.md")).contains("Required action:"));assertFalse(Files.exists(out.resolve("surface.png")));assertFalse(Files.exists(out.resolve("figure.svg")));assertFalse(Files.exists(out.resolve("native-audit.json")));}
    @Test void everyScientificAndPresentationPolicyIsRequired() {var full=model();for(String key:full.keySet()){var options=new LinkedHashMap<>(full);options.remove(key);assertThrows(IllegalArgumentException.class,()->PymolPotentialCli.choices(options),key);}}
    @Test void temperatureAppliesOnlyToExplicitKtPerEUnits() {var options=model();options.put("value-units","volt");assertThrows(IllegalArgumentException.class,()->PymolPotentialCli.choices(options));options.remove("temperature");assertEquals("volt",PymolPotentialCli.choices(options).units());options.put("value-units","arbitrary");assertEquals(0,PymolPotentialCli.choices(options).temperature());options.put("value-units","kt-per-e");assertThrows(IllegalArgumentException.class,()->PymolPotentialCli.choices(options));options.put("temperature","0");assertThrows(IllegalArgumentException.class,()->PymolPotentialCli.choices(options));}
    @Test void radiusSurfaceAndProbeOffsetPoliciesRemainDistinct() {var options=model();options.put("surface-radii","pymol");options.put("surface-solvent","accessible");options.put("sample-location","probe-offset");var choices=PymolPotentialCli.choices(options);assertEquals("pymol",choices.radii());assertEquals("accessible",choices.solvent());assertEquals(1,choices.above());for(String[] pair:new String[][]{{"surface-radii","guess"},{"surface-solvent","default"},{"sample-location","nearest"}}){var bad=model();bad.put(pair[0],pair[1]);assertThrows(IllegalArgumentException.class,()->PymolPotentialCli.choices(bad));}}
    @Test void rampLevelsMustRemainStrictlyIncreasingAtOriginalFloatPrecision() {for(String levels:List.of("0,0,1","1,0,-1","NaN,0,1","-1,1","16777216,16777217,16777218")){var options=model();options.put("ramp-range",levels);assertThrows(IllegalArgumentException.class,()->PymolPotentialCli.choices(options));}}
    @Test void ColorImageQualityProbeAndBufferBoundsAreEnforced() {for(String[] bad:new String[][]{{"low-color","-1,0,0"},{"middle-color","1,1,2"},{"high-color","1,0"},{"background","NaN,0,0"},{"width","399"},{"height","4001"},{"surface-quality","3"},{"probe-radius","-1"},{"buffer","-1"},{"length-units","nanometer"}}){var options=model();options.put(bad[0],bad[1]);assertThrows(IllegalArgumentException.class,()->PymolPotentialCli.choices(options));}}
    @Test void cameraRejectsReflectionsSingularRotationsAndInvalidClips() {List<Double> valid=List.of(1.,0.,0.,0.,1.,0.,0.,0.,1.,0.,0.,-100.,0.,0.,0.,10.,200.,20.);PymolPotentialCli.camera(valid);for(int index:List.of(0,4,15,16)){var bad=new ArrayList<>(valid);bad.set(index,index==0?-1.:0.);assertThrows(IllegalArgumentException.class,()->PymolPotentialCli.camera(bad));}}
    @Test void missingRuntimeSkipsWithRetainedInputsAndLinuxRecovery()throws Exception {var options=options("skip");var run=run(options);assertEquals(3,run.code(),run.err());status(options,"skipped-unavailable-dependency");assertTrue(Files.exists(Path.of(options.get("out"),"partial/source.pqr")));assertTrue(Files.readString(Path.of(options.get("out"),"WARNINGS.md")).contains("Linux Java"));}
    @Test void nonfiniteGridFailsBeforeAnyRuntimeIsRequested()throws Exception {var options=options("nonfinite");Path grid=Path.of(options.get("grid"));String text=Files.readString(grid);text=text.replaceFirst("(?s)(data follows\\s*)[+\\-0-9.eE]+","$1NaN");Files.writeString(grid,text);assertEquals(2,run(options).code());status(options,"failed");}
    @Test void completeGridAndInputResourceBoundsApplyBeforeRuntime()throws Exception {for(String[] bound:new String[][]{{"max-grid-points","8"},{"max-atoms","1"},{"max-bytes","1"}}){var options=options(bound[0]);options.put(bound[0],bound[1]);assertEquals(2,run(options).code());status(options,"failed");}}
    @Test void unicodeOptionsCarrierKeepsSourcePathsAndDirectOverrides()throws Exception {var options=options("unused");Path source=root.resolve("输入.pqr");Files.copy(Path.of(options.get("input")),source);options.put("input",source.toString());Path recipe=root.resolve("options.json");Files.writeString(recipe,RegenieRuntime.json(options));Path out=root.resolve("结果");assertEquals(3,run("--options-file",recipe.toString(),"--out",out.toString()).code());assertFalse(Files.exists(Path.of(options.get("out"))));assertTrue(Files.readString(out.resolve("session.json")).contains("recipe-sha256"));}
    @Test void existingOutputsUnknownOptionsAndDuplicatesArePreserved()throws Exception {var options=options("existing");Path out=Files.createDirectory(Path.of(options.get("out")));Files.writeString(out.resolve("marker"),"keep");assertEquals(2,run(options).code());assertEquals("keep",Files.readString(out.resolve("marker")));assertEquals(2,run("--unknown","x").code());assertEquals(2,run("--out","a","--out","b").code());assertTrue(run("--help").out().contains("float32"));}
    @Test void finiteZeroGridIsAValidSuppliedMapEvenWhenRuntimeMustSkip()throws Exception {var options=options("zero");Path grid=Path.of(options.get("grid"));String original=Files.readString(grid);int start=original.indexOf("data follows")+"data follows".length(),end=original.indexOf("attribute \"dep\"",start);assertTrue(end>start);String zero=original.substring(0,start)+"\n"+"0 0 0\n".repeat(91541)+"0 0\n"+original.substring(end);Files.writeString(grid,zero);assertEquals(3,run(options).code());status(options,"skipped-unavailable-dependency");}
}
